// Audit Logger (shared by all failure branches)
// Input A (validation):  { id, _validation: { valid: false, errors: string[] } }
// Input B (agent error): { ...input fields, error }  - the AI step failed
// Input C (HTTP error):  { ...input fields incl. enrichment, error } - delivery failed
// Output: { id, httpStatus, status, publicErrors, audit: { task, inputs, actions, risks, result, timestamp } }

return $input.all().map(item => {
  const j = item.json;
  const isValidation = j._validation && j._validation.valid === false;

  let httpStatus, status, task, actions, risks, publicErrors;

  if (isValidation) {
    httpStatus = 400;
    status = "rejected";
    task = "Payload validation";
    actions = ["Payload rejected by validator"];
    risks = j._validation.errors ?? [];
    publicErrors = risks;
  } else {
    const msg = typeof j.error === "string" ? j.error : (j.error?.message ?? "Unknown error");
    // If an enrichment object already exists, the AI step succeeded and the HTTP delivery failed
    const fromExternalApi = j.enrichment !== undefined;
    httpStatus = 502;
    status = fromExternalApi ? "external_api_failed" : "ai_failed";
    task = fromExternalApi ? "External API call" : "AI enrichment";
    actions = [fromExternalApi ? "HTTP Request failed" : "Enrichment agent failed"];
    risks = [msg.slice(0, 200)];
    // Internal details are never returned to the caller
    publicErrors = [fromExternalApi ? "Downstream service unavailable" : "Enrichment service unavailable"];
  }

  return {
    json: {
      id: j.id ?? null,
      httpStatus,
      status,
      publicErrors,
      audit: {
        task,
        inputs: [],  // intentionally empty: payload/PII is never written to the log
        actions,
        risks,
        result: status,
        timestamp: new Date().toISOString(),
      },
    },
  };
});

