// DocFlow Ingestion & Parsing - Payload Validator
// Input schema:  { id: string|number, data: string|object|array } (under .body for Webhook input)
// Output schema: { ...payload, _validation: { valid: boolean, errors: string[] } }

const validItems = [];
const rejectedItems = [];

const allItems = $input.all();

// Batch-level check: the input must not be empty
if (!Array.isArray(allItems) || allItems.length === 0) {
  throw new Error("Validation Error: Empty or non-array batch rejected.");
}

for (const item of allItems) {
  // The Webhook node wraps the payload in .body; other sources pass it directly
  const payload = item.json.body ?? item.json;
  const errors = [];

  if (payload === null || typeof payload !== "object" || Array.isArray(payload)) {
    errors.push("Payload must be a JSON object");
  } else {
    if (payload.id === undefined || payload.id === null || payload.id === "") {
      errors.push("Missing required field: id");
    }
    if (payload.data === undefined || payload.data === null) {
      errors.push("Missing required field: data");
    } else if (!["object", "string"].includes(typeof payload.data)) {
      errors.push("Field 'data' must be a string, object or array");
    }
  }

  if (errors.length === 0) {
    validItems.push({ json: { ...payload, _validation: { valid: true, errors: [] } } });
  } else {
    // Audit-friendly: only the id and the error categories leave this node (no PII/secrets)
    rejectedItems.push({
      json: {
        id: payload?.id ?? null,
        _validation: { valid: false, errors },
      },
    });
  }
}

// Valid items first, rejected items last (both flagged)
return [...validItems, ...rejectedItems];

// DocFlow Transformation & Logic - Data Mapper
// Input schema:  { id: string|number, data: string|object|array, source?: string, _validation: {...} }
// Output schema: { id: string, data: <ugyanolyan típus, tisztítva>, metadata: { processedAt, sourceSystem, version } }

// Recursive cleanup: strips < and > from strings, keeps the structure intact
function sanitize(value) {
  if (typeof value === 'string') {
    return value.trim().replace(/[<>]/g, '');
  }
  if (Array.isArray(value)) {
    return value.map(sanitize);
  }
  if (value !== null && typeof value === 'object') {
    return Object.fromEntries(
      Object.entries(value).map(([k, v]) => [k, sanitize(v)])
    );
  }
  return value; // numbers, booleans and null stay unchanged
}

const outputItems = [];

for (const item of $input.all()) {
  const rawData = item.json;

  const cleanedId = String(rawData.id).trim();
  const formattedData = sanitize(rawData.data ?? '');

  const processedItem = {
    id: cleanedId,
    data: formattedData,
    metadata: {
      processedAt: new Date().toISOString(),
      sourceSystem: rawData.source || 'external_webhook',
      version: '1.0.0',
    },
  };

  outputItems.push({ json: processedItem });
}

return outputItems;

