// AI Enrichment Validator (the "reflect" step of the agent loop)
// Input schema:  Agent output { output: { category, priority, summary, confidence, tool_used }, intermediateSteps?: [...] }
// Output schema: { id, data, metadata, enrichment: { category, priority, summary, confidence, status,
//                  needsReview, toolsUsed, agentSteps, warnings } }
// The validator never trusts the model: it re-checks the schema and compares the tools the model
// CLAIMS to have used with the tools that were ACTUALLY called (intermediateSteps).

const CATEGORIES = ["order", "support", "invoice", "complaint", "spam", "other"];
const PRIORITIES = ["low", "medium", "high"];

const mapperItems = $('Data Mapper').all();

return $input.all().map((item, i) => {
  // Pair with the right Data Mapper item even if some items went to the error branch
  const p = Array.isArray(item.pairedItem) ? item.pairedItem[0] : item.pairedItem;
  const idx = typeof p === "number" ? p : (p?.item ?? i);
  const original = mapperItems[idx]?.json ?? {};

  let ai = item.json.output ?? item.json.text ?? null;
  if (typeof ai === "string") {
    try { ai = JSON.parse(ai); } catch { ai = null; }
  }

  const steps = Array.isArray(item.json.intermediateSteps) ? item.json.intermediateSteps : [];
  const toolsUsed = steps.map(s => s?.action?.tool).filter(Boolean);
  const toolErrors = steps.filter(s => /"error"/.test(JSON.stringify(s?.observation ?? ""))).length;

  const errors = [];
  const warnings = [];
  if (!ai || typeof ai !== "object") {
    errors.push("AI output is not a valid object");
  } else {
    if (!CATEGORIES.includes(ai.category)) errors.push("Invalid category");
    if (!PRIORITIES.includes(ai.priority)) errors.push("Invalid priority");
    if (typeof ai.summary !== "string" || ai.summary.trim() === "") errors.push("Missing summary");
    if (typeof ai.confidence !== "number" || ai.confidence < 0 || ai.confidence > 1) errors.push("Invalid confidence");

    const claimedNone = !ai.tool_used || ai.tool_used === "none";
    const mismatch = claimedNone ? toolsUsed.length > 0 : !toolsUsed.includes(ai.tool_used);
    if (mismatch) warnings.push("tool_used does not match the tools actually called");
  }
  if (toolErrors > 0) warnings.push("A tool returned an error");

  const enrichment = errors.length === 0
    ? {
        category: ai.category,
        priority: ai.priority,
        summary: ai.summary.trim().slice(0, 300),
        confidence: ai.confidence,
        status: "classified",
        needsReview: ai.confidence < 0.6 || warnings.length > 0,
        toolsUsed,
        agentSteps: steps.length,
        warnings,
      }
    : {
        category: "unclassified", priority: "medium", summary: "", confidence: 0,
        status: "fallback", needsReview: true, toolsUsed, agentSteps: steps.length,
        warnings: [...errors, ...warnings],
      };

  return { json: { ...original, enrichment } };
});

// Input: `query` is a JSON string like {"items":[{"qty":2,"price":7990}]}
try {
  const input = typeof query === 'string' ? JSON.parse(query) : query;
  const items = Array.isArray(input?.items) ? input.items : [];
  if (items.length === 0 || items.length > 100) {
    return JSON.stringify({ error: 'items must be a non-empty array (max 100 entries)' });
  }
  let total = 0;
  for (const it of items) {
    const qty = Number(it.qty);
    const price = Number(it.price);
    if (!Number.isFinite(qty) || !Number.isFinite(price) || qty < 0 || price < 0) {
      return JSON.stringify({ error: 'invalid qty or price' });
    }
    total += qty * price;
  }
  return JSON.stringify({ total, itemCount: items.length });
} catch (e) {
  return JSON.stringify({ error: 'invalid input' });
}
